package com.ewaste.controller;
import com.ewaste.model.*;import com.ewaste.repository.*;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasRole('ADMIN')") public class AdminController {
 private final UserRepository users;private final PickupRepository pickups;private final WasteReportRepository reports;private final PasswordEncoder encoder;
 public AdminController(UserRepository u,PickupRepository p,WasteReportRepository r,PasswordEncoder e){users=u;pickups=p;reports=r;encoder=e;}
 @GetMapping("/users") public List<Map<String,Object>> users(){return users.findAll().stream().map(u->Map.<String,Object>of("id",u.getId(),"name",u.getName(),"email",u.getEmail(),"role",u.getRole().name(),"points",u.getPoints(),"createdAt",u.getCreatedAt())).toList();}
 @GetMapping("/collectors") public List<Map<String,Object>> collectors(){return users.findByRole(Role.COLLECTOR).stream().map(u->Map.<String,Object>of("id",u.getId(),"name",u.getName(),"email",u.getEmail())).toList();}
 public record CreateAccount(@NotBlank String name,@Email @NotBlank String email,@Size(min=8) String password,@NotNull Role role){}
 @PostMapping("/users") public ResponseEntity<?> createAccount(@RequestBody @jakarta.validation.Valid CreateAccount r){if(r.role()==Role.ADMIN)return ResponseEntity.badRequest().body(Map.of("message","Create admins through secure database/environment setup"));if(users.existsByEmailIgnoreCase(r.email()))return ResponseEntity.status(409).body(Map.of("message","Email already exists"));AppUser u=new AppUser();u.setName(r.name());u.setEmail(r.email().toLowerCase());u.setPassword(encoder.encode(r.password()));u.setRole(r.role());users.save(u);return ResponseEntity.status(201).body(Map.of("id",u.getId(),"name",u.getName(),"email",u.getEmail(),"role",u.getRole()));}
 @GetMapping("/stats") public Map<String,Object> stats(){long completed=pickups.findAll().stream().filter(p->p.getStatus()==WasteStatus.COMPLETED).count();return Map.of("users",users.count(),"reports",reports.count(),"pickups",pickups.count(),"completedPickups",completed,"collectors",users.findByRole(Role.COLLECTOR).size());}
}
